(* [comment removed for export] *)
Definition agreeK (k : Z) (rs : list Z) (rsw : list word) : Prop :=
  forall i, 0 <= i < k -> nth_error rsw (Z.to_nat i) = Some (Z_to_bv 64 (Znth i rs)).

Lemma agreeK_agree : forall tl rs rsw, agreeK (tl + 1) rs rsw -> agree tl rs rsw.
