Section RK.
  Variables (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (x1 x5 x6 x7 x9 x10 x11 x13 x15 x16 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word).
  Variables (m : fmem) (WK tl : Z) (rank : list Z).
  Variable POST : machine_state -> Prop.
  Notation RS := (WK + 52).
  Hypothesis HTL : 1 <= tl <= 12.
  Hypothesis LR : zlen rank = 13.
  Hypothesis RR : Forall (fun v => 0 <= v <= 256) rank.
  Hypothesis HWK : 0 < WK /\ WK + 1492 <= 2^47.
  Hypothesis RKA : u32arr psegs m WK (map (Z_to_bv 64) rank).

  Notation ST pc mm nx next x17 :=
    (MS (mkR x1 sp gp tp x5 x6 x7 (Z_to_bv 64 WK) x9 x10 x11 (Z_to_bv 64 next) x13 (Z_to_bv 64 (WK + 4 * (tl + 1)))
             (Z_to_bv 64 (WK + 4 * nx)) x16 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
        F (Z_to_bv 64 pc) fc None mm (seg_rom psegs)).

  Lemma rk_loop' : forall f n rs rsw next m1 r (x17 : word),
    rank_start_loop f n next rank rs = Ok r -> Z.of_nat f = tl + 1 - n -> 0 <= n <= tl -> 0 <= next <= 256 * n ->
    zlen rs = 13 -> length rsw = 13%nat -> agreeK n rs rsw ->
    u32arr psegs m1 RS rsw -> u32arr psegs m1 WK (map (Z_to_bv 64) rank) ->
    munch [(RS, RS + 52)] m m1 -> wmono psegs m m1 -> mem_inv psegs m1 ->
    (forall m2 rsw' next' (y17 : word), agreeK (tl + 1) r rsw' -> length rsw' = 13%nat -> zlen r = 13 ->
       u32arr psegs m2 RS rsw' -> u32arr psegs m2 WK (map (Z_to_bv 64) rank) ->
       munch [(RS, RS + 52)] m m2 -> wmono psegs m m2 -> mem_inv psegs m2 ->
       evt psegs POST (ST 0x1359c m2 (tl + 1) next' y17)) ->
    evt psegs POST (ST 0x13588 m1 n next x17).
Proof.
