    (forall m2 rsw' next' (y17 : word), agreeK (tl + 1) r rsw' -> length rsw' = 13%nat -> zlen r = 13 ->
       u32arr psegs m2 RS rsw' -> u32arr psegs m2 WK (map (Z_to_bv 64) rank) ->
       munch [(RS, RS + 52)] m m2 -> wmono psegs m m2 -> mem_inv psegs m2 ->
